"""R12: public API docstrings and type hints, and one diagnostics helper.

The scan walks every module under ``cartog/`` (except the generated protobuf
bindings) and fails on a public class, public function, public method, or module
that has no docstring, or on a public function/method with an unannotated
parameter or return value.
"""

from __future__ import annotations

import ast
import logging
import warnings
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parent.parent
PACKAGE = REPO_ROOT / "cartog"

# Generated by grpcio-tools from scip.proto; never hand-edited.
GENERATED = {"scip_pb2.py"}


def _modules() -> list[Path]:
    return [p for p in sorted(PACKAGE.rglob("*.py")) if p.name not in GENERATED]


def _annotated(node: ast.FunctionDef | ast.AsyncFunctionDef) -> list[str]:
    """Names of parameters (and 'return') that carry no annotation."""
    gaps = [
        arg.arg
        for arg in node.args.posonlyargs + node.args.args + node.args.kwonlyargs
        if arg.arg not in ("self", "cls") and arg.annotation is None
    ]
    for star in (node.args.vararg, node.args.kwarg):
        if star is not None and star.annotation is None:
            gaps.append(f"*{star.arg}")
    if node.returns is None:
        gaps.append("return")
    return gaps


def _public_defs(tree: ast.Module) -> list[tuple[str, ast.AST]]:
    """Module-level public defs plus public methods of public classes."""
    found: list[tuple[str, ast.AST]] = []
    for node in tree.body:
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        if node.name.startswith("_"):
            continue
        found.append((node.name, node))
        if isinstance(node, ast.ClassDef):
            for child in node.body:
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    if not child.name.startswith("_"):
                        found.append((f"{node.name}.{child.name}", child))
    return found


def test_public_api_type_hints() -> None:
    missing: list[str] = []

    for path in _modules():
        rel = path.relative_to(REPO_ROOT).as_posix()
        tree = ast.parse(path.read_text(encoding="utf-8"), filename=rel)

        if ast.get_docstring(tree) is None:
            missing.append(f"{rel}: module has no docstring")

        for name, node in _public_defs(tree):
            if ast.get_docstring(node) is None:
                kind = "class" if isinstance(node, ast.ClassDef) else "def"
                missing.append(f"{rel}: {kind} {name} has no docstring")
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for gap in _annotated(node):
                    missing.append(f"{rel}: {name}({gap}) has no annotation")

    assert not missing, (
        "public API is missing docstrings or type hints:\n" + "\n".join(missing)
    )


def test_diagnostics_go_through_one_helper() -> None:
    """Loggers and warnings come from cartog.core.diagnostics, not ad hoc imports."""
    helper = PACKAGE / "core" / "diagnostics.py"
    offenders: list[str] = []

    for path in _modules():
        if path == helper:
            continue
        rel = path.relative_to(REPO_ROOT).as_posix()
        for number, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
            if "import logging" in line or "import warnings" in line:
                offenders.append(f"{rel}:{number}: imports logging/warnings directly")
            if "logging.getLogger(" in line or "warnings.warn(" in line:
                offenders.append(f"{rel}:{number}: bypasses the diagnostics helper")

    assert not offenders, (
        "route logging and warnings through cartog.core.diagnostics:\n"
        + "\n".join(offenders)
    )


def test_diagnostics_helper_contract() -> None:
    from cartog.core.diagnostics import get_logger, warn

    assert isinstance(get_logger(), logging.Logger)
    assert get_logger().name == "cartog"
    assert get_logger("cartog.scip").name == "cartog.scip"

    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        warn("diagnostics probe")
    assert len(caught) == 1
    assert issubclass(caught[0].category, UserWarning)
    assert str(caught[0].message) == "diagnostics probe"
    assert Path(caught[0].filename) == Path(__file__), (
        "warn() must attribute the warning to its caller"
    )


@pytest.mark.parametrize("module", ["cartog.core.model", "cartog.cli"])
def test_public_modules_import_cleanly(module: str) -> None:
    __import__(module)
